    let mut ejs: i32 = -1;
    let mut ejl: i32 = 0;
    let mut i: i32 = bs;
    let mut e: i32 = 0;
    let mut cs: i32 = 0;
    let mut ce: i32 = 0;
    let mut k: i32 = 0;
    let mut nx: i32 = 0;
    let mut prevslot: i32 = 0;
    let mut prevof: i32 = 0;
    let mut sepof: i32 = 0;
    let mut tok: i32 = 0;
    let mut skip: i32 = 0;
    let mut started: i32 = 0;
    let mut j: i32 = 0;
    if pj >= 0 {
        pjtok = sl_get(sl, first + pj, 5);
    }
    if ej >= 0 {
        ejs = bs + sl_get(sl, first + ej, 3);
        ejl = sl_get(sl, first + ej, 4);
    }
