    crate::port::cells_set(fo, (r * 12) + 1, role);
    crate::port::cells_set(fo, (r * 12) + 2, conf);
    crate::port::cells_set(fo, (r * 12) + 3, src);
    crate::port::cells_set(fo, (r * 12) + 4, ts);
    crate::port::cells_set(fo, (r * 12) + 5, tl);
    crate::port::cells_set(fo, (r * 12) + 6, f0);
    crate::port::cells_set(fo, (r * 12) + 7, cnt);
